/*
a = 2.5 x
                    b = x s
                    c = x ⋅ y
                    d = x ∘ y
                    e = x × y
                    where
                    x: ℤ ^ 3
                    y: ℝ ^ 3
                    s: ℝ
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    Eigen::Matrix<DT, 3, 1> a;
    Eigen::Matrix<DT, 3, 1> b;
    DT c;
    Eigen::Matrix<DT, 3, 1> d;
    Eigen::Matrix<DT, 3, 1> e;

    heartlib(
        const Eigen::Matrix<int, 3, 1> & x,
        const Eigen::Matrix<double, 3, 1> & y,
        const double & s)
    {

        // a = 2.5 x
        a = 2.5 * (x).template cast<DT>();
        // b = x s
        b = (x).template cast<DT>() * s;
        // c = x ⋅ y
        c = ((x).template cast<DT>()).dot(y);
        // d = x ∘ y
        d = ((x).template cast<DT>()).cwiseProduct(y);
        // e = x × y
        e = ((x).template cast<DT>()).cross(y);
    }
};

