function output = heartlib(x, y, s)
% output = heartlib(x, y, s)
%
%    a = 2.5 x
%                        b = x s
%                        c = x ⋅ y
%                        d = x ∘ y
%                        e = x × y
%                        where
%                        x: ℤ ^ 3
%                        y: ℝ ^ 3
%                        s: ℝ
    x = reshape(x,[],1);
    y = reshape(y,[],1);

    assert( numel(x) == 3 );
    assert( numel(y) == 3 );
    assert(numel(s) == 1);

    % a = 2.5 x

    a = 2.5 * x;
    % b = x s

    b = x * s;
    % c = x ⋅ y

    c = dot(x,y);
    % d = x ∘ y

    d = x.*y;
    % e = x × y

    e = cross(x, y);
    output.a = a;
    output.b = b;
    output.c = c;
    output.d = d;
    output.e = e;
end

